hn.value:
&lt;p&gt;सही उत्तर &lt;u&gt;&lt;strong&gt;चुनाव आयोग है।&lt;/strong&gt;&lt;/u&gt;&lt;/p&gt;

&lt;p&gt;&lt;img src=&quot;//cdn.testbook.com/images/production/quesImages/quesImage173.png&quot; /&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;strong&gt;संसद सदस्य की अयोग्यता&lt;/strong&gt; से संबंधित किसी भी प्रश्न का निर्णय करते समय, राष्ट्रपति चुनाव आयोग की राय ले सकते हैं।&lt;/li&gt;
	&lt;li&gt;भारत का चुनाव आयोग एक &lt;strong&gt;स्थायी संवैधानिक निकाय&lt;/strong&gt; है।&lt;/li&gt;
	&lt;li&gt;संविधान संसद, राज्य विधानमंडल और राष्ट्रपति और उपराष्ट्रपति के कार्यालयों के लिए &lt;strong&gt;स्वतंत्र और निष्पक्ष चुनाव&lt;/strong&gt; सुनिश्चित करने के लिए एक &lt;strong&gt;स्वतंत्र चुनाव आयोग&lt;/strong&gt; का प्रावधान करता है।&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;मुख्य चुनाव आयुक्त, +2 चुनाव आयुक्त&lt;/strong&gt; होते हैं।&lt;/li&gt;
	&lt;li&gt;मुख्य चुनाव आयुक्त की &lt;strong&gt;नियुक्ति राष्ट्रपति द्वारा की जाती है &lt;/strong&gt;और &lt;strong&gt;अन्य चुनाव आयुक्तों की नियुक्ति राष्ट्रपति द्वारा मुख्य चुनाव आयुक्त के परामर्श के बाद की जाती है, अनुच्छेद 324&lt;/strong&gt; में चुनाव आयोग के परामर्श के बाद आम चुनाव के समय क्षेत्रीय आयुक्तों की नियुक्ति का भी प्रावधान है।&lt;/li&gt;
	&lt;li&gt;चुनाव आयुक्तों की &lt;strong&gt;नियुक्ति 6&amp;nbsp;वर्ष की अवधि &lt;/strong&gt;के लिए की जाती है।&lt;/li&gt;
	&lt;li&gt;वे &lt;strong&gt;पुन: नियुक्ति के लिए पात्र नहीं हैं।&lt;/strong&gt; इसके अलावा, वे अपनी सेवानिवृत्ति के बाद लाभ का कोई भी कार्यालय नहीं रख सकते।&lt;/li&gt;
	&lt;li&gt;भारतीय संविधान के &lt;strong&gt;अनुच्छेद 324&lt;/strong&gt; में, यह &lt;strong&gt;भारत के चुनाव आयोग &lt;/strong&gt;(ईसीआई) की परिकल्पना करता है।&lt;/li&gt;
&lt;/ul&gt;

&lt;div&gt;&amp;nbsp;&lt;/div&gt;

&lt;p align=&quot;left&quot; style=&quot;margin: 6px 0px; padding: 0px; line-height: 1.5em;margin-top: 6px; margin-bottom: 6px; padding: 0px; line-height: 1.5em;&quot;&gt;&lt;span style=&quot;color: rgb(0, 0, 0);   text-align: justify; background-color: rgb(249, 249, 249);&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/additional-information-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Additional Information&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;table border=&quot;1&quot; cellpadding=&quot;1&quot; cellspacing=&quot;1&quot; style=&quot;width: 350px;&quot;&gt;
	&lt;tbody&gt;
		&lt;tr&gt;
			&lt;td&gt;&lt;strong&gt;भारत के मुख्य न्यायाधीश&lt;/strong&gt;&lt;/td&gt;
			&lt;td&gt;भारत के मुख्य न्यायाधीश (सीजेआई) भारत की न्यायपालिका और भारत के सर्वोच्च न्यायालय के प्रमुख हैं। सीजेआई न्यायपालिका के प्रशासनिक कार्यों को भी संचालित करते हैं।&lt;/td&gt;
			&lt;td&gt;&lt;strong&gt;वर्तमान में- &lt;/strong&gt;अरविंद बोबड़े&lt;/td&gt;
		&lt;/tr&gt;
		&lt;tr&gt;
			&lt;td&gt;&lt;strong&gt;महान्यायवादी&lt;/strong&gt;&lt;/td&gt;
			&lt;td&gt;भारत के महान्यायवादी भारत सरकार के मुख्य कानूनी सलाहकार हैं और सभी कानूनी मामलों पर केंद्र सरकार को सलाह देते हैं। भारत का महान्यायवादी देश का सर्वोच्च कानून अधिकारी है।&lt;/td&gt;
			&lt;td&gt;&lt;strong&gt;वर्तमान में- &lt;/strong&gt;केके वेणुगोपाल&lt;/td&gt;
		&lt;/tr&gt;
		&lt;tr&gt;
			&lt;td&gt;&lt;strong&gt;लोकसभा अध्यक्ष&lt;/strong&gt;&lt;/td&gt;
			&lt;td&gt;
			&lt;div&gt;लोकसभा अध्यक्ष सदन&amp;nbsp;के सदस्य और पीठासीन अधिकारी दोनों होते हैं। अध्यक्ष सदन में व्यापार का संचालन करते हैं।&lt;/div&gt;
			&lt;/td&gt;
			&lt;td&gt;&lt;strong&gt;वर्तमान में- &lt;/strong&gt;ओम बिरला&lt;/td&gt;
		&lt;/tr&gt;
	&lt;/tbody&gt;
&lt;/table&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;

en.value:
&lt;p&gt;&lt;u&gt;&lt;strong&gt;Explanation:&lt;/strong&gt;&lt;/u&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;It is the type of fever that does not touch the baseline.&lt;/li&gt;
	&lt;li&gt;It remains above normal for the whole day.&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/additional-information-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Additional Information&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&amp;nbsp;Daily variation in temperature is more than 1-degree centigrade.&amp;nbsp;&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;u&gt;&lt;strong&gt;Reasons&lt;/strong&gt;&lt;/u&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;Infective endocarditis&lt;/li&gt;
	&lt;li&gt;Typhoid&lt;/li&gt;
	&lt;li&gt;Brucellosis&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;img alt=&quot;Fever, fever patterns and diseases called &amp;amp;#39;fever&amp;amp;#39; – A review - ScienceDirect&quot; src=&quot;//storage.googleapis.com/tb-img/production/21/11/F1__Utakarsha_10-11-21_Savita_D9.png&quot; style=&quot;width: 502px; height: 222px;&quot; /&gt;&lt;/p&gt;

hn.value:
&lt;p&gt;&lt;u&gt;&lt;strong&gt;व्याख्या:&lt;/strong&gt;&lt;/u&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;यह बुखार का प्रकार है जो बेसलाइन को नहीं छूता है।&lt;/li&gt;
	&lt;li&gt;यह पूरे दिन सामान्य से ऊपर रहता है।&amp;nbsp;&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/additional-information-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Additional Information&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;तापमान में दैनिक भिन्नता 1 डिग्री सेंटीग्रेड से अधिक होती है।&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;u&gt;&lt;strong&gt;कारण&lt;/strong&gt;&lt;/u&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;इंफेक्टिव एंडोकार्डिटिस&lt;/li&gt;
	&lt;li&gt;टाइफाइड&lt;/li&gt;
	&lt;li&gt;ब्रुसेलोसिस&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;img alt=&quot;Fever, fever patterns and diseases called &#039;fever&#039; – A review - ScienceDirect&quot; src=&quot;//storage.googleapis.com/tb-img/production/21/11/F1__Utakarsha_10-11-21_Savita_D9.png&quot; style=&quot;width: 502px; height: 222px;&quot; /&gt;&lt;/p&gt;

en.value:
&lt;p&gt;&lt;u&gt;&lt;strong&gt;Explanation:-&lt;/strong&gt;&lt;/u&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;b style=&quot;color: rgb(32, 33, 36);  &quot;&gt;Total volume (in mL) divided by time (in min), multiplied by the drop factor.&lt;/b&gt;&lt;b style=&quot;color: rgb(32, 33, 36);  &quot;&gt;​&lt;/b&gt;

	&lt;ul&gt;
		&lt;li&gt;Volume to be administered-1000ml&lt;br /&gt;
		Time-6hr&lt;br /&gt;
		Drop factor-15​&lt;/li&gt;
		&lt;li&gt;&lt;strong&gt;IV Drip rate = 41.67 gtts/min (drops per minute)&lt;/strong&gt;&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;In calculating the drops per minute for an intravenous administration of fluids, it is important to note the three variables involved:&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;The volume to be administered (usually expressed in mL);&lt;/li&gt;
	&lt;li&gt;Administration time (usually in minutes or hours);&lt;/li&gt;
	&lt;li&gt;Drop factor i.e. determined by macro drip tubing (expressed in gtts/mL).&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;strong&gt;The formula used is:&lt;/strong&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;IV Drip rate (Drops per minute) = (Volume to be given in mL x Drop factor in gtts/min) / Time in minutes&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/additional-information-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Additional Information&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&amp;nbsp;The micro drip&lt;span style=&quot;color: rgb(58, 58, 58);  &quot;&gt;&amp;nbsp;set&amp;nbsp;delivers 10 to 20 gtts/mL and is used to infuse large volumes of fluids more rapidly.&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
	&lt;li&gt;&lt;span style=&quot;color: rgb(58, 58, 58);  &quot;&gt;Micro drip tubing delivers 60 gtts/mL and is used for small or very precise amounts of fluid, mostly used in pediatric cases.&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;span style=&quot;color: rgb(58, 58, 58);  &quot;&gt;​&lt;/span&gt;&lt;img alt=&quot;Chapter 6: Dosages of IV Drugs - ppt download&quot; src=&quot;//storage.googleapis.com/tb-img/production/21/11/F1_Utakarsha_10-11-21_Savita_D15.png&quot; style=&quot;width: 316px; height: 221px;&quot; /&gt;&lt;/p&gt;

hn.value:
&lt;p&gt;&lt;u&gt;&lt;strong&gt;व्याख्या:-&lt;/strong&gt;&lt;/u&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;b style=&quot;color: rgb(32, 33, 36);  &quot;&gt;कुल मात्रा (मिलीलीटर में) को समय (मिनट में) से विभाजित करें, ड्रॉप फैक्टर से गुणा करें।&lt;/b&gt;&lt;b style=&quot;color: rgb(32, 33, 36);  &quot;&gt;​&lt;/b&gt;

	&lt;ul&gt;
		&lt;li&gt;दी&amp;nbsp;की जाने वाली मात्रा-1000 मिलीलीटर&lt;br /&gt;
		समय-6 घंटे&lt;br /&gt;
		ड्रॉप फैक्टर-15​&lt;/li&gt;
		&lt;li&gt;&lt;strong&gt;IV ड्रिप दर = 41.67 gtts/मिनट (ड्रॉप प्रति मिनट)&lt;/strong&gt;&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;द्रवों के अंतःशिरा रूप से देने&amp;nbsp;के लिए ड्रॉप प्रति मिनट की गणना करते समय, शामिल तीन चरों पर ध्यान देना महत्वपूर्ण है:&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;दी&amp;nbsp;जाने वाली मात्रा (आमतौर पर मिलीलीटर में व्यक्त);&lt;/li&gt;
	&lt;li&gt;दिया जाने वाला&amp;nbsp;समय (आमतौर पर मिनट या घंटों में);&lt;/li&gt;
	&lt;li&gt;ड्रॉप फैक्टर यानी मैक्रो ड्रिप ट्यूबिंग द्वारा निर्धारित (gtts/mL में व्यक्त)।&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;strong&gt;प्रयुक्त सूत्र है:&lt;/strong&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;IV ड्रिप दर (ड्रॉप प्रति मिनट) = (मिलीलीटर में दी जाने वाली मात्रा x gtts/मिनट में ड्रॉप फैक्टर) / मिनट में समय&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/additional-information-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Additional Information&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;माइक्रो ड्रिप&lt;span style=&quot;color: rgb(58, 58, 58);  &quot;&gt; सेट 10 से 20 gtts/mL देता है और इसका उपयोग बड़ी मात्रा में द्रवों को अधिक तेज़ी से डालने के लिए किया जाता है। &lt;/span&gt;&lt;/li&gt;
	&lt;li&gt;&lt;span style=&quot;color: rgb(58, 58, 58);  &quot;&gt;माइक्रो ड्रिप ट्यूबिंग 60 gtts/mL देती है और इसका उपयोग छोटी या बहुत सटीक मात्रा में द्रव के लिए किया जाता है, ज्यादातर बाल चिकित्सा मामलों में उपयोग किया जाता है।&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;span style=&quot;color: rgb(58, 58, 58);  &quot;&gt;​&lt;/span&gt;&lt;img alt=&quot;Chapter 6: Dosages of IV Drugs - ppt download&quot; src=&quot;//storage.googleapis.com/tb-img/production/21/11/F1_Utakarsha_10-11-21_Savita_D15.png&quot; style=&quot;width: 316px; height: 221px;&quot; /&gt;&lt;/p&gt;

en.value:
&lt;p&gt;&lt;strong&gt;&lt;u&gt;Explanation&lt;/u&gt;: &lt;/strong&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;Nurses learn there are four possible sites:
	&lt;ul&gt;
		&lt;li&gt;The arm (deltoid)&lt;/li&gt;
		&lt;li&gt;Thigh (vastus lateralis)&lt;/li&gt;
		&lt;li&gt;The upper outer posterior buttock (gluteus maximus), also referred to as the dorsogluteal site&lt;/li&gt;
		&lt;li&gt;The lateral hip (gluteus medius) is also called the &lt;strong&gt;ventrolateral site&lt;/strong&gt;.&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;Dorsogluteal&amp;nbsp;muscle is not sufficiently developed to be a safe injection site for infants and small children.&lt;/li&gt;
	&lt;li&gt;Other mentioned sites are safe for I.M. injection in a 2-year-old child.&lt;/li&gt;
&lt;/ul&gt;

hn.value:
&lt;p&gt;&lt;strong&gt;&lt;u&gt;व्याख्या&lt;/u&gt;: &lt;/strong&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;नर्सें जानती हैं कि चार संभावित &lt;span style=&quot;color: rgb(33, 37, 41);&quot;&gt;साइटें&lt;/span&gt; हैं:

	&lt;ul&gt;
		&lt;li&gt;बांह (डेल्टॉयड)&lt;/li&gt;
		&lt;li&gt;जांघ (वैस्टस लेटरलिस)&lt;/li&gt;
		&lt;li&gt;ऊपरी बाहरी पिछली नितंब (ग्लूटियस मैक्सिमस), जिसे डॉर्सोग्लूटियल साइट भी कहा जाता है&lt;/li&gt;
		&lt;li&gt;पार्श्व कूल्हे (ग्लूटियस मेडियस) को &lt;strong&gt;वेंट्रोलैटरल साइट&lt;/strong&gt; भी कहा जाता है।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;डॉर्सोग्लूटियल मांसपेशी शिशुओं और छोटे बच्चों के लिए एक सुरक्षित इंजेक्शन साइट होने के लिए पर्याप्त रूप से विकसित नहीं होती है।&lt;/li&gt;
	&lt;li&gt;अन्य उल्लिखित साइट&amp;nbsp;2 साल के बच्चे में I.M. इंजेक्शन के लिए सुरक्षित हैं।&lt;/li&gt;
&lt;/ul&gt;

en.value:
&lt;p data-end=&quot;70&quot; data-start=&quot;0&quot;&gt;The &lt;strong data-end=&quot;67&quot; data-start=&quot;4&quot;&gt;correct answer is 4) Cool skin distal to the insertion site&lt;/strong&gt;.&lt;/p&gt;

&lt;p data-end=&quot;236&quot; data-start=&quot;138&quot;&gt;&lt;strong data-end=&quot;154&quot; data-start=&quot;138&quot;&gt;Infiltration&lt;/strong&gt; occurs when &lt;strong data-end=&quot;213&quot; data-start=&quot;167&quot;&gt;IV fluid leaks into the surrounding tissue&lt;/strong&gt; instead of the vein.&lt;/p&gt;

&lt;ul data-end=&quot;499&quot; data-start=&quot;136&quot;&gt;
	&lt;li data-end=&quot;499&quot; data-start=&quot;237&quot;&gt;
	&lt;p data-end=&quot;287&quot; data-start=&quot;239&quot;&gt;&lt;strong data-end=&quot;285&quot; data-start=&quot;239&quot;&gt;Common signs and symptoms of infiltration:&lt;/strong&gt;&lt;/p&gt;

	&lt;ul&gt;
		&lt;li data-end=&quot;388&quot; data-start=&quot;292&quot;&gt;&lt;strong data-end=&quot;312&quot; data-start=&quot;292&quot;&gt;Coolness of skin&lt;/strong&gt; at or distal to the insertion site (due to fluid accumulation in tissues)&lt;/li&gt;
		&lt;li data-end=&quot;427&quot; data-start=&quot;393&quot;&gt;&lt;strong data-end=&quot;413&quot; data-start=&quot;393&quot;&gt;Swelling (edema)&lt;/strong&gt; at the site&lt;/li&gt;
		&lt;li data-end=&quot;470&quot; data-start=&quot;432&quot;&gt;&lt;strong data-end=&quot;442&quot; data-start=&quot;432&quot;&gt;Pallor&lt;/strong&gt; around the insertion site&lt;/li&gt;
		&lt;li data-end=&quot;499&quot; data-start=&quot;475&quot;&gt;&lt;strong data-end=&quot;497&quot; data-start=&quot;475&quot;&gt;Pain or discomfort&lt;/strong&gt;&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

&lt;p data-end=&quot;536&quot; data-start=&quot;501&quot;&gt;&lt;strong data-end=&quot;534&quot; data-start=&quot;501&quot;&gt;Explanation of other options:&lt;/strong&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li data-end=&quot;631&quot; data-start=&quot;539&quot;&gt;&lt;strong data-end=&quot;563&quot; data-start=&quot;539&quot;&gt;Redness and swelling&lt;/strong&gt; &amp;rarr; Usually indicates &lt;strong data-end=&quot;610&quot; data-start=&quot;584&quot;&gt;phlebitis or infection&lt;/strong&gt;, not infiltration.&lt;/li&gt;
	&lt;li data-end=&quot;725&quot; data-start=&quot;634&quot;&gt;&lt;strong data-end=&quot;665&quot; data-start=&quot;634&quot;&gt;Blood return in the cannula&lt;/strong&gt; &amp;rarr; Suggests &lt;strong data-end=&quot;704&quot; data-start=&quot;677&quot;&gt;IV is still in the vein&lt;/strong&gt;; not infiltration.&lt;/li&gt;
	&lt;li data-end=&quot;834&quot; data-start=&quot;728&quot;&gt;&lt;strong data-end=&quot;771&quot; data-start=&quot;728&quot;&gt;Difficulty regulating flow with gravity&lt;/strong&gt; &amp;rarr; Could indicate &lt;strong data-end=&quot;813&quot; data-start=&quot;789&quot;&gt;occlusion or kinking&lt;/strong&gt;, not infiltration.&lt;/li&gt;
&lt;/ul&gt;

&lt;p data-end=&quot;856&quot; data-start=&quot;836&quot;&gt;&lt;strong data-end=&quot;854&quot; data-start=&quot;836&quot;&gt;Summary Table:&lt;/strong&gt;&lt;/p&gt;

